------------ lifeCycle ------------
function CameraInput:Awake()
    self._vcam = nil
    self._vcamBlender = nil
    self._vcamParamBlender = nil
    
    self._onSwipeActionEvent = nil
    
    if self:IsWindowsPlatform() then
        self._raycastResultCache = nil
        self._behaviourAction = nil
        self._onUpdate = nil
        self._controlMode = nil
    end

    self.playInputEvent = Bind(self,self.ClearCameraInputAxisValue)
    Events.AddListener(MaidCoffeeConstants.EventNames.UpdateLoungeSceneShowState, self.playInputEvent)
end

function CameraInput:OnDestroy()
    self._vcam = nil
    self._vcamBlender = nil
    self._vcamParamBlender = nil
    
    self:UnlistenSwipeInput()
    self:ClearSwipeInput()
    
    if self:IsWindowsPlatform() then
        self._raycastResultCache:Clear()
        self._raycastResultCache = nil

        if not isNull(self._behaviourAction) then
            self._behaviourAction.UpdateAction = nil
        end 
        self._behaviourAction = nil
        self._onUpdate = nil
        self._controlMode = nil

        self:ShowMouse()
    end
    if self.playInputEvent ~= nil then
        Events.RemoveListener(MaidCoffeeConstants.EventNames.UpdateLoungeSceneShowState,self.playInputEvent)
        self.playInputEvent = nil
    end
end

function CameraInput:Start()
    self:InitSwipeInput()
    
    if self:IsWindowsPlatform() then
        self._raycastResultCache = support.new_list(RaycastResult)

        --- 注册update函数
        self._onUpdate = Bind(self, self.Update)
        self._behaviourAction = KTool.GetOrAddComponent(self.controller.gameObject, BehaviourAction)
        
        self:SetControlMode(Constants.CameraControlMode.MoveMouse)
    else
        self:ListenSwipeInput()
    end
end

function CameraInput:Update()
    --- 现在update里面的逻辑只服务于window平台
    -- 每按下一次 ctl 键, 就会切换 跑步 和 走路 模式:
    if Input.GetKeyDown(KeyCode.LeftControl) or Input.GetKeyDown(KeyCode.RightControl) then
        Events.Broadcast("MaidCoffee_Change_Run_State")
    end

    if Input.GetKeyDown(KeyCode.P) then
        Events.Broadcast(MaidCoffeeConstants.EventNames.MaidCoffeeOpenPcTips)
    end

    if self._controlMode == Constants.CameraControlMode.None then
        return
    end
    
    if Cursor.lockState == CursorLockMode.Locked then
        local xInput = Input.GetAxis(CameraInputXAxisName)
        local yInput = Input.GetAxis(CameraInputYAxisName)
        self:SetAxisValue(0, xInput)
        self:SetAxisValue(1, yInput)
    else
        self:ClearCameraInputAxisValue()
    end

    if Input.GetKey(KeyCode.LeftAlt) then
        self:ShowMouse()
    else
        self:HideMouse()
    end
end
