--- 初始化虚拟相机管理
---@param vcamGO UnityEngine.GameObject 虚拟相机控制器预制体
---@param followTarget UnityEngine.Transform
---@param lookAtTarget UnityEngine.Transform
function CameraInput:InitVCam(vcamGO, followTarget, lookAtTarget, isDisableParamInit)
    self._vcamBlender = KTool.GetComponent(vcamGO, VirtualCameraBlender)
    self._vcamBlender:Init(followTarget, lookAtTarget);
    self._vcamBlender:EnableBlender()
    self._vcamParamBlender = KTool.GetComponent(vcamGO, VirtualCameraParamBlender)
    self._vcamParamBlender:EnableBlender()
    self._vcam = self._vcamBlender:GetCurrentVCam()

    self:InitCinemachineParam(self._vcamBlender, isDisableParamInit)
    self:ClearCameraInputAxisValue()
    
end

--- SetAxisValue
---@param axis integer
---@param value number
function CameraInput:SetAxisValue(axis, value)
    if isNull(self._vcam) then return end
    if axis == 0 then
        local xAxis = self._vcam.m_XAxis
        xAxis.m_InputAxisValue = value
        self._vcam.m_XAxis = xAxis
    elseif axis == 1 then
        local yAxis = self._vcam.m_YAxis
        yAxis.m_InputAxisValue = value
        self._vcam.m_YAxis = yAxis
    end
end

function CameraInput:IsWindowsPlatform()
    if tonumber(IsActiveControlJoystick) == 1 then
        return false
    end
    return GameUtils.IsPCPlatform()
end

function CameraInput:InitEasyTouch()
    EasyTouch.instance.alwaysSendSwipe = true
    EasyTouch.instance.enableUIMode = false
    EasyTouch.SetUICompatibily( true)
end

--- 初始化滑屏输入控制
function CameraInput:InitSwipeInput()
    self:InitEasyTouch()

    self._onSwipeActionEvent = Bind(self, self.OnSwipeActionEvent)
end

--- 清理滑屏输入控制
function CameraInput:ClearSwipeInput()
    EasyTouch.instance.alwaysSendSwipe = false
    EasyTouch.instance.enableUIMode = true
    EasyTouch.SetUICompatibily( false)

    self._onSwipeActionEvent = nil
end

--- 监听滑屏输入事件
function CameraInput:ListenSwipeInput()
    Events.AddListener(Constants.EventNames.OnQuickSwipe2FingerAction, self._onSwipeActionEvent)
end

--- 不监听滑屏输入事件 
function CameraInput:UnlistenSwipeInput()
    Events.RemoveListener(Constants.EventNames.OnQuickSwipe2FingerAction, self._onSwipeActionEvent)
end

---OnSwipeActionEvent
---@param gesture HedgehogTeam.EasyTouch.Gesture
function CameraInput:OnSwipeActionEvent(gesture)
    if isNull(self._vcam) then return end
    if gesture then
        if gesture.type == EasyTouch.EvtType.On_SwipeStart then
            self:ClearCameraInputAxisValue()
            self._vcam = self._vcamBlender:GetCurrentVCam()
        elseif gesture.type == EasyTouch.EvtType.On_Swipe then
            -- x max 250
            -- y max 150
            self:SetAxisValue(0, gesture.deltaPosition.x)
            self:SetAxisValue(1, gesture.deltaPosition.y)
        elseif gesture.type == EasyTouch.EvtType.On_SwipeEnd then
            self:ClearCameraInputAxisValue()
            --self._vcamBlender:BlendTo(VirtualCameraId.Normal)
            self._vcam = self._vcamBlender:GetCurrentVCam()
        end
    end
end

--- 清理相机转动的输入值
function CameraInput:ClearCameraInputAxisValue()
    self:SetAxisValue(0, 0)
    self:SetAxisValue(1, 0)
end

